// resources/client/dashboard/digital-products/product-form-section.tsx
import {BuilderSectionHeader} from '@app/dashboard/stores/store-editor/builder-section-header';
import {Accordion} from '@shadcn/accordion/accordion';
import {Badge} from '@shadcn/badge/badge';
import {Trans} from '@ui/i18n/trans';
import {cn} from '@ui/utils/cn';
import type {LucideIcon} from 'lucide-react';
import type {ReactNode} from 'react';

export type ProductSetupSection = string;

interface ProductFormSectionProps {
  id: ProductSetupSection;
  title: ReactNode;
  description: ReactNode;
  icon: LucideIcon;
  isComplete: boolean;
  count?: number | null;
  hasError?: boolean;
  children: ReactNode;
}

export function ProductFormSection({
  id,
  title,
  description,
  icon,
  isComplete,
  count,
  hasError = false,
  children,
}: ProductFormSectionProps) {
  return (
    <Accordion.Item
      value={id}
      className={cn(hasError && 'border-destructive/40')}
    >
      {/* T4: this section trigger is top-level page content under the page
          h1, so the accordion heading renders as h2 (Base UI's Header
          defaults to h3, which skipped h2 entirely). */}
      <Accordion.Trigger headingRender={<h2 />}>
        <BuilderSectionHeader
          icon={icon}
          isComplete={isComplete}
          title={typeof title === 'string' ? <Trans message={title} /> : title}
          description={
            typeof description === 'string' ? (
              <Trans message={description} />
            ) : (
              description
            )
          }
          trailing={
            count !== null && count !== undefined && count > 0 ? (
              <Badge
                variant="secondary"
                className="h-4 min-w-[16px] px-1"
              >
                {count}
              </Badge>
            ) : undefined
          }
        />
      </Accordion.Trigger>
      <Accordion.Content className="border-t pt-4">
        <div className="max-w-2xl">{children}</div>
      </Accordion.Content>
    </Accordion.Item>
  );
}
